export function initSplitMotion(root = document) {

    if (!window.gsap || !window.SplitText || !window.ScrollTrigger) {
      console.warn("[SplitMotion] GSAP, ScrollTrigger, or SplitText missing");
      return;
    }
  
    gsap.registerPlugin(SplitText, ScrollTrigger);
  
    const PRESETS = {
  
      "fade-up": { opacity: 0, y: 40 },
      "fade-down": { opacity: 0, y: -40 },
      "fade-left": { opacity: 0, x: 40 },
      "fade-right": { opacity: 0, x: -40 },
  
      "zoom-in": { opacity: 0, scale: 0.6 },
  
      "hero": {
        opacity: 0,
        y: 100,
        blur: 12,
        scale: 0.95,
        duration: 1.6,
        ease: "power4.out",
        stagger: 0.03
      }
  
    };
  
    const elements = root.querySelectorAll("[data-split]");
  
    elements.forEach((el) => {
  
      if (el.__SplitMotionInit) return;
      el.__SplitMotionInit = true;
  
      const mode = el.dataset.mode || "words";
  
      const split = new SplitText(el,{ type: mode });
  
      const targets =
        mode === "chars" ? split.chars :
        mode === "lines" ? split.lines :
        split.words;
  
      let presetConfig = {};
  
      for (const presetName in PRESETS) {
        if (el.hasAttribute(`data-${presetName}`)) {
          presetConfig = PRESETS[presetName];
          break;
        }
      }
  
      const fromConfig = {
        opacity: presetConfig.opacity ?? 0,
        x: presetConfig.x ?? 0,
        y: presetConfig.y ?? 0,
        scale: presetConfig.scale ?? 1,
        rotate: presetConfig.rotate ?? 0,
        filter: `blur(${presetConfig.blur ?? 0}px)`
      };
  
      const toConfig = {
        opacity: 1,
        x: 0,
        y: 0,
        scale: 1,
        rotate: 0,
        filter: "blur(0px)",
        duration: presetConfig.duration ?? 0.6,
        stagger: presetConfig.stagger ?? 0.08,
        ease: presetConfig.ease ?? "power2.out",
        scrollTrigger:{
          trigger: el,
          start: "top 85%"
        }
      };
  
      gsap.set(targets, fromConfig);
      gsap.to(targets, toConfig);
  
    });
  
  }